mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM community_post_view_records
    WHERE post_id = #{postId}
        AND member_id = #{memberId}
        AND viewed_at >= DATE_SUB(NOW(), INTERVAL 24 HOUR)
)

SELECT EXISTS (
    SELECT 1
    FROM community_post_view_records
    WHERE post_id = #{postId}
        AND visitor_token = #{visitorToken}
        AND viewed_at >= DATE_SUB(NOW(), INTERVAL 24 HOUR)
)

SELECT image_id AS imageId, post_id AS postId, image_url AS imageUrl, display_order AS displayOrder FROM community_post_images WHERE post_id IN
#{postId}
ORDER BY post_id ASC, display_order ASC

